// Normalizes incoming Instagram or Facebook message for Client Bunny
const raw = $input.first().json;
const body = raw.body || raw;

// 1. Detect Channel (Facebook Messenger vs Instagram DM)
let channel = 'instagram';
if (body.object === 'page' || body.channel === 'facebook' || body.facebook_id || (body.entry && body.entry[0]?.messaging && !body.instagram_username)) {
  channel = 'facebook';
}

// 2. Extract Sender & Identity
let senderId = 'prospect';
let senderName = 'Prospect';
let messageText = '[Message]';

if (body.entry && Array.isArray(body.entry) && body.entry[0]?.messaging) {
  // Standard Meta Graph API format
  const event = body.entry[0].messaging[0];
  senderId = event.sender?.id || 'fb_user';
  senderName = channel === 'facebook' ? `FB User ${senderId.slice(-4)}` : `@user_${senderId.slice(-4)}`;
  messageText = event.message?.text || '[Attachment/Media]';
} else {
  // Direct / webhook payload format
  senderId = body.instagram_username || body.username || body.sender_id || body.user_id || body.id || (channel === 'facebook' ? 'fb_user' : 'ig_user');
  senderName = [body.first_name, body.last_name].filter(Boolean).join(' ') || body.name || (channel === 'instagram' ? `@${senderId}` : `FB User ${senderId}`);
  messageText = body.message || body.text || body.body || '[Direct Message]';
}

return [{
  json: {
    channel: channel,
    senderId: senderId,
    instagram_username: senderId,
    facebook_id: senderId,
    first_name: senderName,
    name: senderName,
    message: messageText,
    timestamp: new Date().toISOString()
  }
}];
